/*
 * A322413  Compound tribonacci sequence with a(n) = A278041(A278039(n)), for
 *          n >= 0.
 * https://oeis.org/A322413
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 21, u16 n <= 60, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula: a(n) = 3 + Σ_{i=0}^{n-1} inc[word[i]]
 * where word is the Tribonacci word generated by the morphism
 *   0 → 01
 *   1 → 02
 *   2 → 0
 * and inc(0) = 13, inc(1) = 11, inc(2) = 7.
 * This yields the A322413 sequence.
 */
#include <stdlib.h>
#include <stddef.h>

seq_t a(idx_t n)
{
    if (n == 0U)
        return (seq_t)3;

    /* Allocate space for the tribonacci word up to n letters. */
    size_t needed = (size_t)n + 1;
    char *cur = (char *)malloc(needed);
    if (!cur)
        return (seq_t)0;
    char *nxt = (char *)malloc(needed);
    if (!nxt) {
        free(cur);
        return (seq_t)0;
    }

    size_t cur_len = 1;
    cur[0] = '0';

    /* Expand the word until it contains at least n letters. */
    while (cur_len < n) {
        /* Every character expands to at most two characters. */
        size_t max_new_len = cur_len * (size_t)2 + 1;
        if (max_new_len > needed) {
            free(nxt);
            needed = max_new_len;
            nxt = (char *)malloc(needed);
            if (!nxt) {
                free(cur);
                return (seq_t)0;
            }
        }

        size_t pos = 0;
        for (size_t i = 0; i < cur_len; ++i) {
            char c = cur[i];
            if (c == '0') {
                nxt[pos++] = '0';
                nxt[pos++] = '1';
            } else if (c == '1') {
                nxt[pos++] = '0';
                nxt[pos++] = '2';
            } else { /* c == '2' */
                nxt[pos++] = '0';
            }
        }

        /* Swap cur and nxt for the next iteration. */
        char *tmp = cur;
        cur = nxt;
        nxt = tmp;
        cur_len = pos;
    }

    /* Sum the increments for the first n letters. */
    seq_t sum = (seq_t)3;  /* a(0) */
    for (idx_t i = 0; i < n; ++i) {
        char c = cur[i];
        if (c == '0')
            sum += (seq_t)13;
        else if (c == '1')
            sum += (seq_t)11;
        else  /* c == '2' */
            sum += (seq_t)7;
    }

    free(cur);
    free(nxt);
    return sum;
}
